import pandas as pd, numpy as np, itertools
from scipy.stats import pearsonr
df=pd.read_csv('bn_sample_10k.csv')
print(df.describe().T)
print("\nCorrelation:")
print(df.corr().round(3))
# partial correlations of all pairs given each subset
cols=list(df.columns)
def pcorr(x,y,Z):
    if Z:
        M=df[[x,y]+Z].values
    else:
        M=df[[x,y]].values
    C=np.cov(M,rowvar=False)
    if Z:
        P=np.linalg.inv(C)
        return -P[0,1]/np.sqrt(P[0,0]*P[1,1])
    return C[0,1]/np.sqrt(C[0,0]*C[1,1])
print("\nMarginal p-values (pearson):")
for x,y in itertools.combinations(cols,2):
    r,p=pearsonr(df[x],df[y]); print(f"{x}-{y}: r={r: .3f} p={p:.2e}")
print("\nPartial correlations (given sets):")
for x,y in itertools.combinations(cols,2):
    rest=[c for c in cols if c not in (x,y)]
    for k in range(1,len(rest)+1):
        for Z in itertools.combinations(rest,k):
            print(f"{x}-{y} | {','.join(Z)}: {pcorr(x,y,list(Z)): .4f}")
EOF
